#!/usr/bin/env bash
# Runs a check script generated by `utils/data-lake-corpus/generate.py checks` with clickhouse-local
# and prints one sorted line per check.
#
# Usage: run_checks.sh <clickhouse-local command> <checks .sql file> [extra clickhouse-local args...]
#
# The script consists of blocks separated by empty lines, one block per corpus file; blocks are
# independent, so they are distributed over a few clickhouse-local processes running in parallel.
# An exception in a check is printed as the label of the check (`<file> <check>`) and the error
# code name, so a file that fails to read shows up in the diff with the reference instead of
# stopping the test.
set -e
local_cmd=$1
checks=$2
shift 2
corpus=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
parquet_testing=$(realpath "$corpus/../../../../contrib/parquet-testing")
parallel=${CORPUS_CHECKS_PARALLEL:-4}

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

sed -e "s|{CORPUS}|$corpus|g" -e "s|{PARQUET_TESTING}|$parquet_testing|g" "$checks" |
    LC_ALL=C awk -v n="$parallel" -v dir="$work" '
        /^--/ { next }
        /^$/ { block++; next }
        { print > (dir "/chunk_" (block % n) ".sql") }
    '

for chunk in "$work"/chunk_*.sql
do
    # shellcheck disable=SC2086
    $local_cmd --session_timezone=UTC --ignore-error "$@" --queries-file "$chunk" > "$chunk.out" 2>&1 &
done
wait

cat "$work"/chunk_*.sql.out | LC_ALL=C awk '
    /^@@ / { file = substr($0, 4); next }
    /^Received exception/ { in_error = 1; name = ""; next }
    in_error && match($0, /\([A-Z][A-Z0-9_]+\)$/) { name = substr($0, RSTART + 1, RLENGTH - 2) }
    in_error && /^\(query: SELECT '\''/ {
        label = $0; sub(/^\(query: SELECT '\''/, "", label); sub(/'\''.*/, "", label)
        print label "\t" name; in_error = 0; next
    }
    in_error && /^\(query: / { print file " setup\t" name; in_error = 0; next }
    in_error { next }
    { print }
' | LC_ALL=C sort
